UPDATE decision_nodes SET data = '{"type":"question","module":4,"title":"Imaging & Localization","body":"**Goal:** Identify bleeding source to guide intervention.\n\n**Imaging options based on hemodynamic status:**\n\n**CTA (CT Angiography):**\n• First-line for hemodynamically significant bleeding\n• Detects bleeding rates ≥0.3-0.5 mL/min\n• Can localize for embolization or surgery\n\n**Colonoscopy:**\n• First-line for stable patients\n• Diagnostic AND therapeutic\n• Timing (ACG 2023): NONURGENT colonoscopy for most — urgent colonoscopy within 24h does NOT improve rebleeding, mortality, or other outcomes. In stable patients, colonoscopy within 14 days is as effective as within 24h. Reserve urgent colonoscopy for ongoing hemodynamically significant bleeding.\n\n**Nuclear Medicine (Tagged RBC Scan):**\n• Detects slower bleeding (0.1-0.4 mL/min)\n• Less specific for localization\n• Useful if intermittent bleeding","citation":[1,6],"options":[{"label":"CTA First","description":"Hemodynamically significant or unstable","next":"lgib-cta","urgency":"urgent"},{"label":"Colonoscopy First","description":"Stable patient, diagnostic + therapeutic intent","next":"lgib-colonoscopy"},{"label":"Nuclear Medicine Scan","description":"Intermittent bleeding, stable patient","next":"lgib-nuclear"}],"summary":"CTA for unstable/significant; colonoscopy for stable (diagnostic + therapeutic); nuclear for intermittent"}'::jsonb
