UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Colonoscopy","body":"**Timing (ACG 2023):**\n• **NONURGENT colonoscopy** for most hospitalized patients — urgent colonoscopy within 24h does NOT improve rebleeding, mortality, transfusion, or LOS. In stable patients, within 14 days is as effective as within 24h.\n• **Urgent** only for ongoing hemodynamically significant bleeding not controlled by resuscitation (consider CTA ± embolization first in the unstable patient)\n• **Elective/outpatient** for low-risk patients (Oakland ≤8) within 7-14 days\n\n**Bowel prep:**\n• Rapid prep (4-6L PEG over 3-4h) improves visualization\n• May skip prep for urgent colonoscopy if significant blood\n\n**Therapeutic interventions:**\n• Hemostatic clips\n• Epinephrine injection\n• Thermal coagulation (APC, bipolar)\n• Band ligation for hemorrhoids\n\n**Common findings:**\n• Diverticulosis (30-65%)\n• Hemorrhoids (5-20%)\n• Angiodysplasia (3-15%)\n• Post-polypectomy bleeding\n• Colorectal neoplasm","citation":[1,6],"next":"lgib-intervention","summary":"NONURGENT colonoscopy for most (ACG 2023: 24h does not beat 14d); urgent only for ongoing significant bleeding; therapeutic options include clips, injection, coagulation"}'::jsonb
